import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Determinazione di alcuni tipi particolari di funzione","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/c_analisi/ci/cibb.md","filePath":"lezioni/c_analisi/ci/cibb.md"}`),a={name:`lezioni/c_analisi/ci/cibb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="determinazione-di-alcuni-tipi-particolari-di-funzione" tabindex="-1">Determinazione di alcuni tipi particolari di funzione <a class="header-anchor" href="#determinazione-di-alcuni-tipi-particolari-di-funzione" aria-label="Permalink to “Determinazione di alcuni tipi particolari di funzione”">​</a></h1><p>Veramente la determinazione del tipo di funzione (intera, razionale, fratta, ...) deve essere fatta all&#39;inizio prima della determinazione del campo di esistenza. Qui consideriamo alcuni tipi di funzione che ci aiutano a costruire il loro grafico e precisamente:</p><ul><li>le funzioni pari</li><li>le funzioni dispari</li><li>le funzioni periodiche</li></ul><hr><ul><li>Per le funzioni pari basterà costruire solo metà grafico poi farne il simmetrico rispetto all&#39;asse delle <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span> (simmetria assiale). In pratica lo ribalto attorno all&#39;asse <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span>. In blu la parte ribaltata.</li><li>Per le funzioni dispari basterà costruire solo metà grafico poi farne il simmetrico rispetto all&#39;origine (simmetria centrale). In pratica prima lo ribalto rispetto all&#39;asse <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span> ed il risultato lo ribalto ancora attorno all&#39;asse <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>. In blu la parte ribaltata due volte.</li><li>Per le funzioni periodiche basterà costruire un periodo e poi ripeterlo su tutto l&#39;asse reale. In blu il periodo ripetuto una prima volta.</li></ul>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};